-- 108 DRY RUN (generated by drafts/tools/build-108-dryrun.mjs: 108 + three proofs + a deliberate error) - PALLETS: THE DELIVERY MOVEMENT WRITTEN BY THE BASE (U5, owner 27/10 answer 4a: "kathe paradomeni paraggelia me
-- antallagi prepei na exei kinisi paradosis, o,ti seira kai na ginoun ta pragmata").
--
-- Plan: docs/data-audit/2026-10/2026-10-27-alexia-pallets.md, step 3 = U5, section E4.
-- Number 108: 107 ran 8/11 (the missing-delivery list and its one definition, pl_v_missing_delivery).
-- The owner runs it in the Supabase SQL editor AFTER 15:00, with an explicit yes, one step at a time:
--   1. 108_pl_delivery_trigger_dryrun.sql   this block + the proofs below, then a deliberate error: NOTHING kept
--   2. 108_pl_delivery_trigger.sql          (this file)
--   3. 108_pl_delivery_trigger_verify.sql   read-only, one row
-- THEN merge the front-end PR (core/pallet-feed.js stops writing DELIVERY): never the front end first, or no one
-- writes the delivery between the two.
-- ASCII only. ONE DO block = ONE statement: an error anywhere undoes all of it.
--
-- WHAT IT ADDS
--   * pl_h_delivery_write(order, stop, why): one confirmed DELIVERY per unloading stop with pallets, "full exchange"
--     as the browser writes it today (taken = given = the stop's pallets, net 0), counterparty = the order's client,
--     point = the stop's point. ONE per stop: INSERT ... ON CONFLICT on pl_mov_stop_once (073) DO NOTHING, so a
--     delivery the accountant corrected (reversal + replacement) is never written again. Each row written gets its
--     audit_log 'create' row through plan_h_audit, actor 'system' (the page says "aftomata"). The same exceptions as
--     the browser feeder (plOrderGate): a split leg (parent_order_id) and an own stock lot are not client
--     deliveries; an order without a client cannot carry one (it stays in the missing list, where it is said).
--   * trigger pl_delivery_from_order: AFTER UPDATE OF status, pallet_exchange ON orders, ONLY on the transition
--     INTO "Delivered with exchange" (status reached Delivered while exchange is on, or exchange switched on while
--     Delivered). A re-save of an order that already was both writes NOTHING: the 49 old stops of the list stay as
--     they are (owner 27/10 answer 4b: the accountant fills them herself). Day: the day of the switch for a status
--     transition (as the browser: today); for an exchange switched on later, the order's actual delivery day, else
--     the stop's day, else today.
--   * trigger pl_delivery_from_stop: AFTER INSERT ON order_stops of an unloading stop, when its order already is
--     Delivered with exchange (a stop added afterwards).
--   * B-54 (the auditor's count of live public triggers) 64 -> 66, in the same transaction.
-- NOT HERE: the browser keeps its own write until its PR is merged (it finds the row already written and skips);
-- the auditor's check for deliveries after this day (F-32) needs a GRANT for tms_check_runner first (107 verify:
-- runner_reads_bases = false) and comes on its own.
-- RUNTIME: two CREATE TRIGGER (a short lock on orders / order_stops, lock_timeout 5s), no table rewrite, no row of an
-- existing table written but B-54's. statement_timeout 60s.
-- REVERSE: 108_pl_delivery_trigger_rollback.sql (drops the triggers and the functions, B-54 back; rows written stay).
-- EXPECTED: NOTICE "108 OK: ..." ; then verify: result = '108 in place'.

DO $do$
DECLARE
  v_trg0 int; v_trg1 int; v_k int; v_t0 timestamptz := clock_timestamp();
  v_m0 int; v_ord0 int; v_m1 int; v_m2 int; v_a1 int; v_a2 int; v_oid bigint; v_stops int;
BEGIN
  PERFORM set_config('lock_timeout', '5s', true);
  PERFORM set_config('statement_timeout', '60s', true);
  PERFORM set_config('search_path', 'public', true);

  -- ===== PART 0: GUARDS (nothing written before them) =====
  IF to_regprocedure('public.pl_h_delivery_write(bigint,bigint,text)') IS NOT NULL THEN
    RAISE EXCEPTION '108: pl_h_delivery_write already exists - 108 has run, nothing to do';
  END IF;
  IF to_regprocedure('public.plan_h_audit(text,text,text,text,text,jsonb,jsonb)') IS NULL THEN
    RAISE EXCEPTION '108: plan_h_audit (072) is missing - stop';
  END IF;
  IF to_regclass('public.pl_mov_stop_once') IS NULL THEN
    RAISE EXCEPTION '108: pl_mov_stop_once (073) is missing - the one-per-stop rule would not hold - stop';
  END IF;
  IF to_regclass('public.pl_v_missing_delivery') IS NULL THEN
    RAISE EXCEPTION '108: pl_v_missing_delivery (107) is missing - run 107 first';
  END IF;
  SELECT count(*) INTO v_trg0 FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid
    JOIN pg_namespace ns ON ns.oid = c.relnamespace
   WHERE NOT t.tgisinternal AND t.tgenabled <> 'D' AND ns.nspname = 'public';
  IF NOT EXISTS (SELECT 1 FROM monitoring.checks WHERE id = 'B-54' AND red_value::int = v_trg0 AND baseline IS NULL) THEN
    RAISE EXCEPTION '108: B-54 red_value is not the live trigger count % - re-measure', v_trg0;
  END IF;

  -- ===== PART 1: THE ONE WRITER =====
  CREATE FUNCTION public.pl_h_delivery_write(p_order bigint, p_stop bigint, p_why text) RETURNS int
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$
  DECLARE
    v_o orders%ROWTYPE; v_s record; v_day date; v_new pl_movements%ROWTYPE; v_n int := 0;
  BEGIN
    SELECT * INTO v_o FROM orders WHERE id = p_order;
    IF NOT FOUND OR v_o.deleted_at IS NOT NULL OR v_o.status IS DISTINCT FROM 'Delivered' OR v_o.pallet_exchange IS NOT TRUE THEN
      RETURN 0;
    END IF;
    -- the browser feeder's exceptions (core/pallet-feed.js plOrderGate)
    IF v_o.parent_order_id IS NOT NULL THEN RETURN 0; END IF;
    IF EXISTS (SELECT 1 FROM stock_lots WHERE order_id = p_order AND deleted_at IS NULL) THEN RETURN 0; END IF;
    -- no client = no counterparty (one_counterparty CHECK): skipped, never a failed save; the stop stays in
    -- pl_v_missing_delivery, where the accountant and the auditor see it
    IF v_o.client_id IS NULL THEN RETURN 0; END IF;
    v_day := (now() AT TIME ZONE 'Europe/Athens')::date;
    FOR v_s IN SELECT id, location_id, round(pallets)::int AS pallets, datetime FROM order_stops
                WHERE order_id = p_order AND stop_type = 'Unloading' AND deleted_at IS NULL AND coalesce(pallets, 0) >= 1
                  AND (p_stop IS NULL OR id = p_stop)
                ORDER BY id LOOP
      v_new := NULL;
      INSERT INTO pl_movements (movement_date, counterparty_type, client_id, location_id, event_type, taken, given,
                                order_stop_id, order_id, status, created_by, confirmed_by, confirmed_at)
      VALUES (CASE WHEN p_why = 'status' THEN v_day ELSE coalesce(v_o.actual_delivery_date, v_s.datetime, v_day) END,
              'CLIENT', v_o.client_id, v_s.location_id, 'DELIVERY', v_s.pallets, v_s.pallets,
              v_s.id, p_order, 'confirmed', 'system', 'system', now())
      ON CONFLICT (order_stop_id, event_type)
        WHERE order_stop_id IS NOT NULL AND status <> 'reversed' AND event_type = ANY (ARRAY['LOADING'::text, 'DELIVERY'::text])
        DO NOTHING
      RETURNING * INTO v_new;
      IF v_new.id IS NOT NULL THEN
        PERFORM plan_h_audit('system', 'system', 'create', 'pl_movements', v_new.id::text, NULL,
          to_jsonb(v_new) || jsonb_build_object('source', 'trigger:108', 'why', p_why));
        v_n := v_n + 1;
      END IF;
    END LOOP;
    RETURN v_n;
  END $f$;

  -- ===== PART 2: THE TWO TRIGGERS =====
  CREATE FUNCTION public.pl_h_delivery_from_order() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$
  BEGIN
    -- ONLY the transition into "Delivered with exchange": a re-save that changes neither writes nothing (the old
    -- stops of the missing list stay the accountant's).
    IF NEW.status = 'Delivered' AND NEW.pallet_exchange IS TRUE AND NEW.deleted_at IS NULL
       AND NOT (OLD.status IS NOT DISTINCT FROM 'Delivered' AND OLD.pallet_exchange IS TRUE) THEN
      PERFORM pl_h_delivery_write(NEW.id, NULL, CASE WHEN OLD.status IS DISTINCT FROM 'Delivered' THEN 'status' ELSE 'exchange' END);
    END IF;
    RETURN NULL;
  END $f$;
  CREATE TRIGGER pl_delivery_from_order AFTER UPDATE OF status, pallet_exchange ON public.orders
    FOR EACH ROW EXECUTE FUNCTION public.pl_h_delivery_from_order();

  CREATE FUNCTION public.pl_h_delivery_from_stop() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$
  BEGIN
    -- a NEW unloading stop of an order that already is Delivered with exchange (pl_h_delivery_write checks the order)
    PERFORM pl_h_delivery_write(NEW.order_id, NEW.id, 'new_stop');
    RETURN NULL;
  END $f$;
  CREATE TRIGGER pl_delivery_from_stop AFTER INSERT ON public.order_stops
    FOR EACH ROW WHEN (NEW.stop_type = 'Unloading' AND NEW.order_id IS NOT NULL AND NEW.deleted_at IS NULL)
    EXECUTE FUNCTION public.pl_h_delivery_from_stop();

  -- ===== PART 3: CLOSED =====
  REVOKE ALL ON FUNCTION public.pl_h_delivery_write(bigint, bigint, text) FROM PUBLIC, anon, authenticated;
  REVOKE ALL ON FUNCTION public.pl_h_delivery_from_order() FROM PUBLIC, anon, authenticated;
  REVOKE ALL ON FUNCTION public.pl_h_delivery_from_stop() FROM PUBLIC, anon, authenticated;

  -- ===== PART 4: B-54 FOLLOWS =====
  SELECT count(*) INTO v_trg1 FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid
    JOIN pg_namespace ns ON ns.oid = c.relnamespace
   WHERE NOT t.tgisinternal AND t.tgenabled <> 'D' AND ns.nspname = 'public';
  IF v_trg1 <> v_trg0 + 2 THEN RAISE EXCEPTION '108: triggers % -> % (expected +2)', v_trg0, v_trg1; END IF;
  UPDATE monitoring.checks SET red_value = v_trg1 WHERE id = 'B-54' AND red_value::int = v_trg0;
  GET DIAGNOSTICS v_k = ROW_COUNT;
  IF v_k <> 1 THEN RAISE EXCEPTION '108: B-54 not updated (% rows)', v_k; END IF;

  -- DRY RUN ONLY: the proofs, then everything is undone.
  SELECT count(*), count(DISTINCT order_id) INTO v_m0, v_ord0 FROM public.pl_v_missing_delivery;
  UPDATE public.orders SET pallet_exchange = pallet_exchange WHERE id IN (SELECT order_id FROM public.pl_v_missing_delivery);
  SELECT count(*) INTO v_m1 FROM public.pl_v_missing_delivery;
  SELECT count(*) INTO v_a1 FROM public.audit_log WHERE actor = 'system' AND after_data ->> 'source' = 'trigger:108';
  IF v_m1 <> v_m0 OR v_a1 <> 0 THEN RAISE EXCEPTION '108 DRY RUN FAILED: a re-save wrote (missing % -> %, audit %)', v_m0, v_m1, v_a1; END IF;
  SELECT order_id INTO v_oid FROM public.pl_v_missing_delivery ORDER BY delivered_on DESC, order_stop_id LIMIT 1;
  IF v_oid IS NOT NULL THEN
    SELECT count(*) INTO v_stops FROM public.pl_v_missing_delivery WHERE order_id = v_oid;
    UPDATE public.orders SET pallet_exchange = false WHERE id = v_oid;
    UPDATE public.orders SET pallet_exchange = true WHERE id = v_oid;
    SELECT count(*) INTO v_m2 FROM public.pl_v_missing_delivery;
    SELECT count(*) INTO v_a2 FROM public.audit_log WHERE actor = 'system' AND after_data ->> 'source' = 'trigger:108';
    IF v_m2 <> v_m0 - v_stops OR v_a2 <> v_stops THEN
      RAISE EXCEPTION '108 DRY RUN FAILED: the transition of order % wrote % (audit %), expected %', v_oid, v_m0 - v_m2, v_a2, v_stops;
    END IF;
    IF public.pl_h_delivery_write(v_oid, NULL, 'status') <> 0 THEN RAISE EXCEPTION '108 DRY RUN FAILED: a second write on order %', v_oid; END IF;
  END IF;
  RAISE EXCEPTION 'DRY RUN 108 finished: re-save of % listed orders wrote 0; transition of order % wrote % deliveries (audit %); triggers % -> %; % ms - NOTHING kept',
    v_ord0, coalesce(v_oid::text, 'none'), coalesce(v_stops, 0), coalesce(v_a2, 0),
    v_trg0, v_trg1, round(extract(epoch FROM clock_timestamp() - v_t0) * 1000);
END
$do$;
